  function openInvoiceMail(invoice){state.preview=invoice;const form=$('#mailForm'),settings={senderName:form.elements.senderName.value||'個別指導ステップ【請求書】',replyTo:form.elements.replyTo.value||'',subject:form.elements.subject.value||'【請求書】送付のご案内（個別指導ステップから）',body:form.elements.body.value||'',testRecipient:form.elements.testRecipient.value||''};$('#mailInvoiceNumber').textContent=invoice.invoiceNumber;$('#mailTo').textContent=settings.testRecipient?`${settings.testRecipient}（テスト送信先／本来の宛先：${invoice.email}）`:invoice.email;$('#mailCc').textContent=invoice.cc||'なし';$('#mailSender').textContent=settings.senderName;$('#mailReplyTo').textContent=settings.replyTo||'なし';$('#mailSubject').value=settings.subject;$('#mailBody').value=C.renderTemplate(settings.body,{'取引先名':invoice.partnerName,'敬称':invoice.honorific||'様','有効日数':form.elements.validDays.value||45,'ダウンロードURL':'（送信時にCloudflareのURLを発行します）'});const pending=['送信待ち','送信中'].includes(String(invoice.sendStatus||'')),resend=C.isSentStatus(invoice.sendStatus);$('#confirmInvoiceMail').textContent=pending?'送信処理を再開':resend?'この内容で再送':'この内容で送信';const status=$('#invoiceMailStatus');status.textContent=pending?'この請求書は送信待ちです。「送信処理を再開」を押すと送信を完了します。':'';status.className=pending?'mail-submit-status working':'mail-submit-status hidden';$('#invoiceMailDialog').showModal();}
