  async function deleteInvoice(event){event.preventDefault();const number=state.pendingDeleteInvoiceNumber,button=$('#confirmDeleteInvoice');if(!number||button.disabled)return;button.disabled=true;button.textContent='削除しています…';try{await cloudApi(`/api/app/invoices/${encodeURIComponent(number)}`,{method:'DELETE'});state.invoices=state.invoices.filter(invoice=>String(invoice.invoiceNumber)!==String(number));state.selectedInvoiceNumber='';$('#deleteInvoiceDialog').close();renderCreate();renderInvoices();alert(`請求書 No. ${number} を削除しました。`,'success');}catch(e){alert(e.message,'error');}finally{button.disabled=false;button.textContent='本当に削除する';}}
